function applyMove(state, m) {
  const p = ALL_MOVES[m], n = new Uint8Array(24);
  for (let i = 0; i < 24; i++) n[i] = state[p[i]];
  return n;
}

function isSolved(state) {
  for (let i = 0; i < 24; i++) if (state[i] !== SOLVED_STATE[i]) return false;
  return true;
}

// Corner extraction
const CORNER_STICKERS = [
  [3,9,20],[2,8,17],[0,13,16],[1,12,21],
  [5,11,22],[4,10,19],[6,15,18],[7,14,23]
];
const CORNER_UD_COLOR = [0,0,0,0,1,1,1,1];

// Numeric key: sort 3 color values a<=b<=c, key = a*36+b*6+c
const _CSF = new Uint8Array(216);
_CSF.fill(255);
(function() {
  for (let c = 0; c < 8; c++) {
    const s = CORNER_STICKERS[c];
    let a=SOLVED_STATE[s[0]], b=SOLVED_STATE[s[1]], cc=SOLVED_STATE[s[2]];
    if(a>b){let t=a;a=b;b=t;} if(b>cc){let t=b;b=cc;cc=t;} if(a>b){let t=a;a=b;b=t;}
    _CSF[a*36+b*6+cc] = c;
  }
})();

const FACT = [1,1,2,6,24,120,720,5040];

function _heuristic(state) {
  const remaining = [0,1,2,3,4,5,6,7];
  let pIdx = 0, oIdx = 0;
  for (let pos = 0; pos < 8; pos++) {
    const s = CORNER_STICKERS[pos];
    let a=state[s[0]], b=state[s[1]], c=state[s[2]];
    if(a>b){let t=a;a=b;b=t;} if(b>c){let t=b;b=c;c=t;} if(a>b){let t=a;a=b;b=t;}
    const cid = _CSF[a*36+b*6+c];
    const udColor = CORNER_UD_COLOR[cid];
    const colors = [state[s[0]], state[s[1]], state[s[2]]];
    const orient = (colors[0]===udColor) ? 0 : (colors[1]===udColor ? 1 : 2);
    const ri = remaining.indexOf(cid);
    remaining.splice(ri, 1);
    pIdx += ri * FACT[7 - pos];
    oIdx  = oIdx * 3 + orient;
  }
  return Math.max(PERM_H[pIdx], ORIENT_H[oIdx]);
}

