function _shouldPrune(move, last) {
  if (last < 0) return false;
  const f = (move/3)|0, lf = (last/3)|0;
  if (f === lf) return true;
  if (f === lf+1 && (f&1) === 1) return true;
  return false;
}

let _sol = null;
const _path = new Uint8Array(20);

function _search(state, g, bound, last, depth) {
  const h = _heuristic(state);
  const f = g + h;
  if (f > bound) return f;
  if (h === 0) { _sol = Array.from(_path.slice(0, depth)); return -1; }
  let min = 99;
  for (let m = 0; m < 18; m++) {
    if (_shouldPrune(m, last)) continue;
    _path[depth] = m;
    const t = _search(applyMove(state, m), g+1, bound, m, depth+1);
    if (t === -1) return -1;
    if (t < min) min = t;
  }
  return min;
}

function idaStar(state) {
  if (isSolved(state)) return [];
  _sol = null;
  let bound = _heuristic(state);
  while (bound <= 20) {
    const t = _search(state, 0, bound, -1, 0);
    if (_sol !== null) return _sol;
    if (t === 99) return null;
    bound = t;
  }
  return null;
}

